first_accepted_patch:
--- a/rtl/fifo.v
+++ b/rtl/fifo.v
@@ -56,7 +56,9 @@
             // Occupancy counter update
             case ({do_push, do_pop})
                 2'b10: item_count <= item_count + 1'b1;
+                2'b01: item_count <= item_count - 1'b1;
+                2'b11: item_count <= item_count;
                 default: item_count <= item_count;
             endcase
         end
     end

